Json encode_object(const InputMedia& value, Request* request) {
    return to_json(value.value, request);
}

void decode_object(const Json& json, InputMedia& value) {
    if (!json.is_object()) {
        throw std::invalid_argument("expected union Object");
    }
    if (json.at("type") == "animation") {
        value.value.emplace<0>(from_json<InputMediaAnimation>(json));
        return;
    }
    if (json.at("type") == "audio") {
        value.value.emplace<1>(from_json<InputMediaAudio>(json));
        return;
    }
    if (json.at("type") == "document") {
        value.value.emplace<2>(from_json<InputMediaDocument>(json));
        return;
    }
    if (json.at("type") == "live_photo") {
        value.value.emplace<3>(from_json<InputMediaLivePhoto>(json));
        return;
    }
    if (json.at("type") == "photo") {
        value.value.emplace<4>(from_json<InputMediaPhoto>(json));
        return;
    }
    if (json.at("type") == "video") {
        value.value.emplace<5>(from_json<InputMediaVideo>(json));
        return;
    }
    throw std::invalid_argument("unknown or invalid InputMedia alternative");
}

